const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const N = readInt();
    if (N === null) return;
    const K = readInt();
    const C = readInt();

    const pref = new Int32Array(N + 1);
    let totalSum = 0;
    for (let i = 1; i <= N; i++) {
        const val = readInt();
        totalSum += val;
        pref[i] = pref[i - 1] + val;
    }

    let prev = new Int32Array(N + 1);
    let curr = new Int32Array(N + 1);

    for (let j = 1; j <= K; j++) {
        const min_i = j * C;
        const max_i = N - (K - j) * C;

        let best = prev[min_i - C] + (pref[min_i] - pref[min_i - C]);
        curr[min_i] = best;

        for (let i = min_i + 1; i <= max_i; i++) {
            const cand = prev[i - C] + (pref[i] - pref[i - C]);
            if (cand < best) {
                best = cand;
            }
            curr[i] = best;
        }

        const temp = prev;
        prev = curr;
        curr = temp;
    }

    const minCovered = prev[N];
    const maxUncovered = totalSum - minCovered;

    console.log(maxUncovered);
}

main();
